// Original CotW Psychic/PhrenicAmplifications text (MIT), pinned source.
using System.Collections.Generic;
namespace CallOfTheWild.Wrath.Prototype {
 internal static class PsychicTexts01458 {
  internal static readonly Dictionary<string,string[]> Data=new Dictionary<string,string[]> {
   ["Pain"]=new[]{"Pain","Mental blocks prevent your immense inborn psychic energies from flowing freely. They are unleashed only when you suffer pain.\nDiscipline Powers: Your powers allow you to cause and endure pain."},
   ["PainfulReminderBuff"]=new[]{"Painful Reminder Allowed","As a swift action, you can cause an enemy to take 1d6 points of damage if you dealt damage to that enemy with a spell since the start of your previous turn. You can use this ability a number of times per day equal to 3 + your Charisma modifier. This damage increases to 2d6 at 8th level and to 3d6 at 15th level.\nIf your painful reminder deals at least 5 points of damage, you regain 1 point in your phrenic pool."},
   ["LiveOn"]=new[]{"Live On","At 5th level, you can use lay on hands as though you were a paladin of 3 levels lower than your psychic level.\nYou also gain access to mercies as though you were a paladin of 3 levels lower than your psychic level. You can target only yourself with lay on hands or mercies gained from this discipline."},
   ["AgonizingWoundFeature"]=new[]{"Agonizing Wound","At 13th level, whenever you cast a spell that deals damage to a creature, you can also make that creature frightened or sickened (your choice) for one round. If you expend two uses of this ability, you can instead have the creature become dazed, nauseated, or panicked for 1 round. The creature can attempt a Will saving throw to negate this effect. You can use this ability a number of times per day equal to 3 + your Charisma modifier. This is a mind-affecting pain effect."},
   ["Psychedelia"]=new[]{"Psychedelia","You ingest hallucinogens to expand your mind. Experimentation and study show you which ones will have the greatest effect. Your psychedelic forays put you into a different mental space from others, and normal people don’t really understand you.\nDiscipline Powers: You distort your own mind and perceptions, and can impress your altered states onto others."},
   ["PsychedeliaCognatogen"]=new[]{"Cognatogen","Once per day, you can create a cognatogen, a mutagen-like mixture that heightens one mental ability score at the expense of a physical ability score. When you imbibe a cognatogen, you gain a +2 natural armor bonus and a +4 alchemical bonus to the selected ability score for 1 minute per psychic level. In addition, while the cognatogen is in effect, you take a –2 penalty to one of your physical ability scores. If the cognatogen enhances your Intelligence, it applies a penalty to your Strength. If it enhances your Wisdom, it applies a penalty to your Dexterity.\nIf it enhances your Charisma, it applies a penalty to your Constitution. Otherwise, this ability works just like the alchemist’s mutagen ability. When the effect of the cognatogen ends, you take 2 points of ability damage to the ability score penalized by the cognatogen. If you have both alchemist and psychic levels, these levels stack to determine the duration of your cognatogen and the DC of the save a non-alchemist must attempt if he drinks your cognatogen. If you gain discoveries, you can take the grand cognatogen and greater cognatogen discoveries to improve your cognatogen. The infuse mutagen discovery and the persistent mutagen class ability apply to cognatogens. However, even if you have alchemist levels, the duration of your cognatogen remains 1 minute per level (instead of 10 minutes per level)."},
   ["WarpedBrainFeature"]=new[]{"Warped Brain","At 5th level, your mind becomes difficult to comprehend. When another creature uses a mind-affecting spell or ability against you, that creature must attempt a Will save. If it fails, it becomes nauseated for 1 round. This ability triggers even if you succeed at your save (or are otherwise unaffected by the spell or ability), but doesn’t apply if you’re a willing subject of the spell. This is a mind-affecting effect."},
   ["HallucinogenicAuraCooldownBuff"]=new[]{"Hallucinogenic Aura Cooldown","At 13th level, a mental field emanates from you, touching the minds of those nearby.\nAny creature within 20 feet of you must succeed at a Will save or be confused for 1d4 rounds. A creature that succeeds at its saving throw is immune to your hallucinogenic aura for 24 hours. A creature that fails its save doesn’t need to continue making saves while it’s confused by this aura, and becomes immune for 24 hours once its confusion ends.\nThis is a mind-affecting effect. You’re immune to your own hallucinogenic aura, as well as your allies.\n"},
   ["Abomination"]=new[]{"Abomination","Your mind is impure, tainted by outside forces. These might be monstrous ancestors whose blood still flows within you, or powerful and unknowable psychic forces that intrude upon your mind. Like a psychic disease, this influence consumes part of your brain, creating a dark counterpart to your normal self. Every time you call forth a psychic spell, you’re drawing on this dangerous force—and potentially giving it a greater hold on you. This malign influence might stem from creatures like rakshasas and aboleths, or perhaps malign entities that dwell in the voids between the stars.\nDiscipline Powers: Your powers allow the dark influences to take over, and it can be difficult to come back from the brink."},
   ["MorphicForFeature"]=new[]{"Morphic Form","At 5th level, while manifesting your dark half, you gain DR 5. This damage reduction can be overcome by a random type of damage each time you manifest your dark half (either bludgeoning, cold iron or magic)."},
   ["PsychicSafeGuardFeature"]=new[]{"Psychic Safeguard","At 13th level, you project constant mental defenses, gaining spell resistance equal to 8 + your caster level. While manifesting your dark half, this spell resistance increases to 16 + your caster level."},
   ["DarkHalfBuff"]=new[]{"Dark Half","By allowing the dark forces to overcome you, you can enter a state of instinctual cruelty as a swift action.\nWhile you’re manifesting your dark half, you increase the DCs of your psychic spells by 1, gain a +2 morale bonus on Will saves, and become immune to fear effects. Whenever you cast a spell that deals damage while manifesting your dark half, you can cause any creature that took damage from the spell to also take 1 point of bleed damage. The amount of bleed damage increases to 2 points at 5th level and to 3 points at 13th level. While manifesting your dark half, you can’t use any Charisma-, Dexterity-, or Intelligence-based skills (except Mobility and Intimidate) or any ability that requires patience or concentration other than casting spells using psychic magic, using phrenic amplifications, or attempting to return to normal. You can attempt to return to your normal self as a free action, but must succeed at an Intelligence check with a DC equal to 10. If you fail, you continue to manifest your dark half and can’t attempt to change back for 1 round.\nYou can manifest your dark half for a number of rounds per day equal to 3 + 1/2 your psychic level + your Charisma modifier; when these rounds are expended, you return to your normal self without requiring a concentration check."},
   ["DarkHalfBleedBuff"]=new[]{"Dark Half: Bleed","This creature takes 1 point of bleed damage per turn. The amount of bleed damage increases to 2 points at 5th level and to 3 points at 13th level. Bleeding can be stopped through the application of any spell that cures hit point damage (even if the bleed is ability damage)."},
   ["MimicMetamagicSelection"]=new[]{"Mimic Metamagic","When the psychic gains this amplification, she chooses two metamagic feats; she need not have these feats to select them. When she casts a spell, she can spend points from her phrenic pool to apply one of the chosen feats to the linked spell without increasing the spell’s level or casting time. She must spend a number of points equal to double the number of levels by which the feat normally increases a spell’s level (minimum 2 points). If the metamagic feat alters the spell’s casting time in a different way than the standard rules for a spontaneous caster using a metamagic feat (as in the case of Quicken Spell), it changes the casting time accordingly. The psychic can still apply metamagic feats she knows to the spell while using this amplification, increasing the casting time and spell level as normal. This amplification can be applied only to a spell that the chosen metamagic feat could normally affect, and only if the spellcaster can cast spells of a high enough level that she would be able to apply the metamagic feat in question to the linked spell. For example, an 11th-level psychic could spend 8 points to quicken a 1st-level spell, but couldn’t quicken a 2nd-level spell because she’s unable to cast 6th-level spells. This ability doesn’t require her to have any free spell slots in the relevant level, however, so the psychic in the example could quicken a 1st-level spell even if she had cast all her 5th-level spells for the day. A psychic can select this amplification multiple times, adding two additional options to the list of metamagic feats she can apply using this amplification each time."},
   ["DualAmplificationFeature"]=new[]{"Dual Amplification","When the psychic uses this major amplification, she chooses two other amplifications or major amplifications she knows to apply to the same linked spell. She can’t apply the same amplification to the linked spell more than once, even if she can use that amplification for multiple different effects."},
   ["1SpaceRendingSpellBuff"]=new[]{"Space-rending Spell ","The psychic can warp space with her mind, teleporting herself as she casts her linked spell. She teleports herself 10 feet per point she spends from her phrenic pool (as dimension door). The maximum number of points she can spend in this way is equal to the linked spell’s level."},
   ["SynapticShockTargetBuff"]=new[]{"Synaptic Shock Target","The psychic manipulates an enemy’s mind with brute force, causing mental harm beyond that done by her linked spell. She can spend 1 point from her phrenic pool when casting a mind-affecting linked spell to select one of the spell’s targets. If the target is affected by the linked spell, that target is confused for 1 round. This amplification can be applied only to a mind-affecting spell that can affect a number of targets or that has an area. It has no effect on creatures that are immune to mind-affecting effects, unless the linked spell is able to affect such creatures (such as a spell that has both will of the dead and synaptic shock applied to it via dual amplification)."},
   ["WillOfTheDeadBuff"]=new[]{"Will of the Dead","Even undead creatures can be affected by the psychic’s mind-affecting spells. The psychic can spend 2 points from her phrenic pool to overcome an undead creature’s immunity to mind-affecting effects for the purposes of the linked spell. This ability functions even on mindless undead, but has no effect on creatures that aren’t undead. This amplification can be linked only to spells that have the mind-affecting descriptor."},
   ["UndercastSurge1Buff"]=new[]{"Undercast Surge ","When the psychic undercasts a spell, she can spend points from her phrenic pool to increase the spell’s effective level, essentially using up a lower-level spell slot to cast a higher-level version of the spell. This costs 2 points per spell level increased. She can’t use this ability to cast a version higher than the version she knows. For instance, a psychic who knows mind thrust III but not mind thrust IV could cast mind thrust II and spend 2 points to treat it as mind thrust III, but couldn’t spend 4 points to treat it as mind thrust IV. This amplification can be linked only to spells that can be undercast."}
  };
  internal static string Name(string key)=>Data[key][0];
  internal static string Description(string key)=>Data[key][1];
 }
}
